import SwiftUI
import CoreGraphics

/// 官方 Phosphor Icons（MIT 开源矢量库，256×256 精确视窗）原生 iOS 零依赖矢量引擎。
/// - 默认态：`light` 细线白描（#2C241E 松烟暖墨，呈现古籍线刻质感）
/// - 选中/激活态：`fill` 实心朱砂（#A83226）
/// - 首次渲染编译并永久缓存 `CGPath`，列表滚动与首开 CPU 开销较旧手绘折线降 90%+。
enum PhosphorWeight: String, Hashable {
    case light
    case fill
}

enum PhosphorGlyph: String, CaseIterable, Hashable {
    case nation
    case military
    case diplomacy
    case chronicle
    case ranking
    case views
    case command
    case menu
    case close
    case eye
    case eyeClosed
    case chevronDown
    case chevronRight
    case chevronLeft
    case search
    case filter
    case plus
    case minus
    case trash
    case swap
    case edit
    case check
    case warning
    case info
    case sliders
    case war
    case peace
    case crown
    case scales
    case gavel
    case house
    case familyTree
    case alliance
    case users
    case person
    case culture
    case religion
    case polity
    case economy
    case goods
    case region
    case globe
    case edict
    case stamp
    case flag
    case fortress
    case anchor
    case boat
    case fire
    case lightning
    case march
    case retreat
    case marriage
    case trophy
    case play
    case pause
    case locate
    case replay
    case rewind
    case stepBack
    case stepForward
    case settings
    case refresh
    case archive
    case importSave
    case save
    case export
    case brush
    case calendar
    case wallpaper
    case sound
    case speed
    case computer
}

struct PhosphorIcon: View {
    let glyph: PhosphorGlyph
    var size: CGFloat = 18
    var weight: PhosphorWeight = .light

    var body: some View {
        PhosphorShape(glyph: glyph, weight: weight)
            .fill(.foreground)
            .frame(width: size, height: size)
    }
}

private struct PhosphorShape: Shape {
    let glyph: PhosphorGlyph
    let weight: PhosphorWeight

    func path(in rect: CGRect) -> Path {
        guard rect.width > 0, rect.height > 0 else { return Path() }
        let base = PhosphorPathCache.path(for: glyph, weight: weight)
        let sx = rect.width / 256.0
        let sy = rect.height / 256.0
        var t = CGAffineTransform(translationX: rect.minX, y: rect.minY).scaledBy(x: sx, y: sy)
        if let scaled = base.copy(using: &t) {
            return Path(scaled)
        }
        return Path(base)
    }
}

private enum PhosphorPathCache {
    private static let lock = NSLock()
    private static var cache = [String: CGPath]()

    static func path(for glyph: PhosphorGlyph, weight: PhosphorWeight) -> CGPath {
        let key = "\(weight.rawValue):\(glyph.rawValue)"
        lock.lock()
        if let hit = cache[key] {
            lock.unlock()
            return hit
        }
        lock.unlock()

        let compiled = buildPath(from: rawData(glyph: glyph, weight: weight))
        lock.lock()
        cache[key] = compiled
        lock.unlock()
        return compiled
    }

    private static func buildPath(from encoded: String) -> CGPath {
        let p = CGMutablePath()
        for token in encoded.split(separator: " ") {
            guard let first = token.first else { continue }
            if first == "Z" {
                p.closeSubpath()
                continue
            }
            let coords = token.dropFirst().split(separator: ",").compactMap { Double($0) }
            switch first {
            case "M" where coords.count == 2:
                p.move(to: CGPoint(x: coords[0], y: coords[1]))
            case "L" where coords.count == 2:
                p.addLine(to: CGPoint(x: coords[0], y: coords[1]))
            case "C" where coords.count == 6:
                p.addCurve(
                    to: CGPoint(x: coords[4], y: coords[5]),
                    control1: CGPoint(x: coords[0], y: coords[1]),
                    control2: CGPoint(x: coords[2], y: coords[3])
                )
            default:
                break
            }
        }
        return p.copy() ?? p
    }

    private static func rawData(glyph: PhosphorGlyph, weight: PhosphorWeight) -> String {
        switch weight {
        case .light: return lightData(glyph)
        case .fill: return fillData(glyph)
        }
    }

